import { z } from "zod";
import { generateSwiftValidation } from "./swift-validation.ts";

export const swiftValidationFixtureDirectory =
  "swift/Tests/SwiftValidationGeneratorTests/Generated";

export function generateSwiftValidationFixture(): string {
  // Test-only quicktype-shaped structs let us exercise maxLength and scalar
  // const without changing the frozen production contract or generated files.
  const source = `import Foundation
public struct LotseProtocolBundle: Codable, Equatable, Sendable {
    public let text: String
    public let number: Double
    public let token: String
    public let date: String
    public let labels: [String]?
    public let marker: String
    public enum CodingKeys: String, CodingKey {
        case text = "text"
        case number = "number"
        case token = "token"
        case date = "date"
        case labels = "labels"
        case marker = "marker"
    }
}
public enum JSONValue: Codable {
    case bool(Bool)
    case double(Double)
    case string(String)
    case unionArray([JSONValue])
    case unionMap([String: JSONValue])
    case null
}
`;
  const schema = z.toJSONSchema(
    z.strictObject({
      text: z.string().min(2).max(3),
      number: z.int().gt(0).lt(10),
      token: z.literal("fixed"),
      date: z.iso.datetime({ offset: true }),
      labels: z.array(z.string().max(2)).optional(),
      marker: z.string().regex(/^[\d]{2}\$/),
    }),
  );
  return (
    "// Generated by scripts/swift-validation-fixture.ts; do not edit.\n" +
    generateSwiftValidation(source, schema, [])
  );
}
